UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"The organisation has no playbook for prompt injection, rogue tools, poisoned memory, model drift or evidence compromise.","customer_symptom":"A user or operator may observe the organisation has no playbook for prompt injection, rogue tools, poisoned memory, model drift or evidence compromise; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"an external content author, compromised source, malicious user, or unsafe model output can exploit or trigger the condition in the organisation has no playbook for prompt injection, rogue tools, poisoned memory, model drift or evidence compromise, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["system prompt, retrieved context and persistent memory","source documents, messages and generated outputs","tool endpoints and downstream systems","financial, administrative or state-changing actions","model and dependency artefacts","build, registry and deployment provenance"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["production agents"],"threat_actor_or_failure_source":"an external content author, compromised source, malicious user, or unsafe model output","trust_boundary":"The test crosses the boundary between production agents and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If the organisation has no playbook for prompt injection, rogue tools, poisoned memory, model drift or evidence compromise, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-101 incident plan, role, provider coordination or recovery-process change","ARL-KB-101 new model, memory, tool or autonomous capability","ARL-KB-101 prompt-injection, rogue-tool, poisoned-memory, drift or evidence-compromise incident","ARL-KB-101 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='6f036028450c6b108a9781992fc9ec68648ec4ceb6ae6ce290bb6cf13eef2c77', updated_at='2026-08-06' WHERE id='ARL-KB-101';
UPDATE risk_knowledge_checks SET objective='Determine whether the organisation can detect, contain, investigate and recover from agent-specific incidents including prompt injection, rogue tools, poisoned memory, model drift and evidence compromise.', method='Review the incident plan and run an owner-authorised tabletop using a realistic agent attack chain from detection through triage, containment, evidence preservation, provider coordination, customer communication, recovery and post-incident reassessment. Verify named roles and decision authority are usable in practice.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-101 assessed system, version, environment and scope for AI-specific incident response is missing","ARL-KB-101 control configuration or source location showing how reduce the likelihood and impact of ai-specific incident response is missing and make the remaining risk visible.","ARL-KB-101 positive and abuse inputs with expected and observed outputs for system prompt, retrieved context and persistent memory and source documents, messages and generated outputs","ARL-KB-101 policy, authorization, tool or audit events proving whether the tested ai-specific incident response is missing path executed","ARL-KB-101 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-101 passes only when “AI-specific incident response is missing” is not reproducible through the documented abuse cases, the valid workflow remains bounded to system prompt, retrieved context and persistent memory and source documents, messages and generated outputs, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-101 fails when the organisation has no playbook for prompt injection, rogue tools, poisoned memory, model drift or evidence compromise, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-101 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='afba3caef0b78b24a35d3f79e9f0ba5965514675ae011df79854d6e79b718c9a', updated_at='2026-08-06' WHERE entry_id='ARL-KB-101';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of ai-specific incident response is missing and make the remaining risk visible.', recommended_remediation='Define severity, roles, containment, evidence capture, provider coordination, notification, recovery and lessons-learned procedures.', default_owner='Incident response owner', priority='P1', implementation_principles_json='["ARL-KB-101: Include agent-specific attack and failure modes in incident response planning.","ARL-KB-101: Define accountable detection, containment, evidence, communication and recovery roles.","ARL-KB-101: Reassess affected controls and evidence after material incidents before returning to normal operation."]', monitoring='For ARL-KB-101, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Incident response owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-101 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-101: “AI-specific incident response is missing” is no longer reproducible against the exact remediated version.","ARL-KB-101: Authorised in-scope use completes successfully, remains within the documented asset scope for ai-specific incident response is missing, and produces no unintended side effect.","ARL-KB-101: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-101: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='bfb19024fcc9f4b5122b7b4d19da7792c34dbe54ca52ebf2d020945c6de7cc9d', updated_at='2026-08-06' WHERE entry_id='ARL-KB-101';
