UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"A harmful prompt, model, policy or tool change cannot be reverted without data loss or further exposure.","customer_symptom":"A user or operator may observe a harmful prompt, model, policy or tool change cannot be reverted without data loss or further exposure; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"an external content author, compromised source, malicious user, or unsafe model output can exploit or trigger the condition in a harmful prompt, model, policy or tool change cannot be reverted without data loss or further exposure, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["system prompt, retrieved context and persistent memory","source documents, messages and generated outputs","tool endpoints and downstream systems","financial, administrative or state-changing actions","model and dependency artefacts","build, registry and deployment provenance"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["production agents"],"threat_actor_or_failure_source":"an external content author, compromised source, malicious user, or unsafe model output","trust_boundary":"The test crosses the boundary between production agents and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If a harmful prompt, model, policy or tool change cannot be reverted without data loss or further exposure, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-104 release, migration, model, prompt, policy or tool deployment change","ARL-KB-104 rollback mechanism, artifact retention or data-compatibility change","ARL-KB-104 failed rollback, unidentified release or rollback-data-loss evidence","ARL-KB-104 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='05143133579bcf6eaa2195ce81ca5606488703792d6a550deab0759f5c9ff863', updated_at='2026-08-06' WHERE id='ARL-KB-104';
UPDATE risk_knowledge_checks SET objective='Determine whether a harmful model, prompt, policy, tool or application release can be reverted safely to a known version without unacceptable data loss or continued exposure.', method='Deploy a controlled bad change in staging and verify exact version identification, rollback authority, immutable artifact availability, data and schema compatibility, operational recovery and alert closure. Confirm rollback returns the system to the intended known state rather than merely redeploying another unverified version.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-104 assessed system, version, environment and scope for Release rollback is unavailable or unsafe","ARL-KB-104 control configuration or source location showing how reduce the likelihood and impact of release rollback is unavailable or unsafe and make the remaining risk visible.","ARL-KB-104 positive and abuse inputs with expected and observed outputs for system prompt, retrieved context and persistent memory and source documents, messages and generated outputs","ARL-KB-104 policy, authorization, tool or audit events proving whether the tested release rollback is unavailable or unsafe path executed","ARL-KB-104 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-104 passes only when “Release rollback is unavailable or unsafe” is not reproducible through the documented abuse cases, the valid workflow remains bounded to system prompt, retrieved context and persistent memory and source documents, messages and generated outputs, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-104 fails when a harmful prompt, model, policy or tool change cannot be reverted without data loss or further exposure, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-104 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='429551332ce37e4194a543503b51ba7118f02b71c53b924160b1eb04bedf07c6', updated_at='2026-08-06' WHERE entry_id='ARL-KB-104';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of release rollback is unavailable or unsafe and make the remaining risk visible.', recommended_remediation='Keep immutable artefacts and reversible migrations, separate configuration from data, use canaries and document rollback decision authority.', default_owner='Release owner', priority='P1', implementation_principles_json='["ARL-KB-104: Retain immutable known-good release artifacts and exact version metadata.","ARL-KB-104: Design data and configuration changes so rollback safety is explicitly understood and tested.","ARL-KB-104: Define human rollback decision authority and validate recovery before closing the incident or release failure."]', monitoring='For ARL-KB-104, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Release owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-104 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-104: “Release rollback is unavailable or unsafe” is no longer reproducible against the exact remediated version.","ARL-KB-104: Authorised in-scope use completes successfully, remains within the documented asset scope for release rollback is unavailable or unsafe, and produces no unintended side effect.","ARL-KB-104: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-104: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='2a8586773d09b168f187f95a90198c05141af555dc75fc5465e0d0faf78948e8', updated_at='2026-08-06' WHERE entry_id='ARL-KB-104';
